class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if (!head) return nullptr;
        std::stack<ListNode*> st;
        ListNode* curr = head;
        while (curr) {
            st.push(curr);
            curr = curr->next;
        }
        ListNode* newHead = st.top(); st.pop();
        curr = newHead;
        while (!st.empty()) {
            curr->next = st.top(); st.pop();
            curr = curr->next;
        }
        curr->next = nullptr;
        return newHead;
    }
};

